/// <summary>
/// MPJ_19962_MDRPOTransactionalMissingFields kavya 25/3/2022
/// The Entity extension
/// </summary>
[ExtensionOf(dataentityviewstr(PurchPurchaseOrderConfirmationHeaderEntity))]
final class METPurchPurchaseOrderConfirmationHeaderEntity_Extension
{
}

Method.Source:
    /// <summary>
    /// Map data fields to virtual fields
    /// </summary>
    public void postLoad()
    {        
        METPlannerCodeSetup METPlannerCodeSetup; 

        select firstonly1 PlannerCodePersonnelNumber from METPlannerCodeSetup 
            where METPlannerCodeSetup.PlannerCode == this.METPOPlannerCode;
        
        HcmWorker HcmWorker = HcmWorker::find(METPlannerCodeSetup.PlannerCodePersonnelNumber);

        this.METPOPlannerContactName    = HcmWorker.name();
        this.METPOPlannerContactEmail   = HcmWorker.email();
        this.METPOPlannerContactPhone   = HcmWorker.phone();

        next postload();
    }

    /// <summary>
    /// getPODeliveryShiptoGLN method COC
    /// </summary>
    /// <returns> string value</returns>
    private static server str getPODeliveryShiptoGLN()
    {
        str                 locationId;
        SysDictTable        dictInventLocation = new SysDictTable(tableNum(InventLocation));
        str                 DeliveryShiptoGLN;

        locationId =  SysComputedColumn::returnField(dataentityviewstr(PurchPurchaseOrderConfirmationHeaderEntity), dataEntityDataSourceStr(PurchPurchaseOrderConfirmationHeaderEntity, PurchTableAllVersions),
            fieldStr(PurchTableAllVersions, InventLocationId));

        DeliveryShiptoGLN = strFmt(@"@MET:METSQLQuery3",
            dictInventLocation.fieldName(fieldNum(InventLocation, METPODeliveryShiptoGLN), DbBackend::Sql),
            dictInventLocation.name(DbBackend::Sql),
            dictInventLocation.fieldName(fieldNum(InventLocation, InventLocationId), DbBackend::Sql),
            locationId);

        return DeliveryShiptoGLN;
    }

    /// <summary>
    /// Initialize from vendor site setup table
    /// </summary>
    public void initFromVendSiteSettingSetup()
    {    
        PurchTable purchTable = purchTable::find(this.PurchaseOrderNumber);

        this.METPOBackOrderSetting                    = purchtable.getVendSiteSettingsSetupFieldValues(fieldNum(METVendSiteSettingsSetup,DefaultBackOrderSetting));
        this.METPOExpressReceiptSetting               = purchtable.getVendSiteSettingsSetupFieldValues(fieldNum(METVendSiteSettingsSetup,ExpressReceiptSetting));
        this.METPOASNSetting                          = purchtable.getVendSiteSettingsSetupFieldValues(fieldNum(METVendSiteSettingsSetup,ASNSetting));
        this.METPOMinOrderValue                       = purchtable.getVendSiteSettingsSetupFieldValues(fieldNum(METVendSiteSettingsSetup,MinOrderValue));
        this.METPOSubMode                             = purchtable.getVendSiteSettingsSetupFieldValues(fieldNum(METVendSiteSettingsSetup,POSubMode));
        this.METPOIHGEmailEDIAddress                  = purchtable.getVendSiteSettingsSetupEmailEDI();
    }

/// <summary>
/// Initial the default data 
/// </summary>
public void defaultRow()
{
    next defaultRow();
    this.initFromVendSiteSettingSetup();
}
